INSERT INTO "Binara_fashion".conversations (id, phone_number, message, direction, message_type, metadata, created_at, user_id) VALUES
('3529df91-2f70-4c7c-8555-63d3e13d1f94', '94774782345', 'ආයුබෝවන් ඩොක්ටර්. මට පොඩි ගැටලුවක් තියෙනවා අහගන්න. මගේ පුතාට දැන් අවුරුදු හයයි. එයාට පොඩි කාලේ ඉඳන්ම මේ සෙම ගතිය වැඩියි. ඉතින් ඒක නිසා මම එයාට නිතරම වගේ නෙබියුලයිස් කරනවා. මේ විදියට දිගින් දිගටම නෙබියුලයිස් කරන එක එයාගේ පෙනහළුවලට හෝ වෙනත් දේකට බලපානවද කියලා මට පොඩ්ඩක් දැනගන්න පුළුවන්ද? ඒ වගේම මේකෙන් ගොඩක් අතුරු ආබාධ එනවද? පොඩ්ඩක් පැහැදිලි කරලා දෙනවා නම් ලොකු උදව්වක් ඩොක්ටර්. ස්තූතියි.', 'inbound', 'ptt', '{"raw": {"id": "evt_01m7t3c3hgscad95y77yhkzgck", "me": {"id": "94743437071@c.us", "lid": "206755497832582@lid", "pushName": "Binara Fashion", "messageCapping": {"cycleEnd": 1, "mvStatus": "NOT_ELIGIBLE", "oteStatus": "NOT_ELIGIBLE", "usedQuota": 0, "cycleStart": 0, "totalQuota": 0, "cappingStatus": "NONE"}, "reachoutTimelock": null}, "event": "message", "engine": "NOWEB", "payload": {"id": "false_204612426551305@lid_A59D3E5358B8DAC06EBF39292B32DB64", "ack": 2, "body": null, "from": "204612426551305@lid", "_data": {"key": {"id": "A59D3E5358B8DAC06EBF39292B32DB64", "fromMe": false, "remoteJid": "204612426551305@lid", "participant": "", "remoteJidAlt": "94774782345@s.whatsapp.net", "addressingMode": "lid"}, "status": 3, "message": {"audioMessage": {"ptt": true, "url": "https://mmg.whatsapp.net/v/t62.7117-24/794190997_1477804537676187_2217406292949482192_n.enc?ccb=11-4&oh=01_Q5Aa6AFnNbO1f25UIHQi2lEA7iH4aPvGwioYjxEPOXAtKaCGmg&oe=6B2663C7&_nc_sid=5e03e0&mms3=true", "seconds": 2, "mediaKey": "Fki+svSZqh3xGRjpyNE563QQg3FNJhNiE4CxXuur9Xw=", "mimetype": "audio/ogg; codecs=opus", "waveform": "AAAAAAAAAAAEDhMYGx4gIiUnKywrKysuRldhVkQsJjVaX15WPThQMh4iOEc+R1FSUEpCQEFHTVJNRTxDR0YuIw==", "directPath": "/v/t62.7117-24/794190997_1477804537676187_2217406292949482192_n.enc?ccb=11-4&oh=01_Q5Aa6AFnNbO1f25UIHQi2lEA7iH4aPvGwioYjxEPOXAtKaCGmg&oe=6B2663C7&_nc_sid=5e03e0", "fileLength": "5248", "fileSha256": "pNazTqalKIAMDDGHS6ya4jkAFeyvGUj8Wny5w9L/dLM=", "contextInfo": {}, "fileEncSha256": "vlGgVwa30RHCEFQrRjH7ZW1FR5Yj7ceTfW95Nomok28="